/* Order detail: copying, compact dates and refund preparation. No money transfers. */
(function () {
    'use strict';
    var FEEDBACK_MS = 3200; // Lifetime of the single fixed copy feedback surface.
    var IS_PREVIEW = !!document.querySelector('script[src="assets/preview-only.js"]'); // Reuse the preview's central notice.
    var REFUND_REASON_CODES = ['customer_request', 'payment_error', 'service_not_provided', 'technical_issue', 'other']; // UI enum mapped to existing PaymentRefundForm.reason by the preparation adapter.
    var REFUND_REASON_LABELS = { customer_request: 'По запросу клиента', payment_error: 'Ошибочная или повторная оплата',
        service_not_provided: 'Услуга не оказана', technical_issue: 'Техническая проблема' };
    var REFUND_REQUEST_TIMEOUT_MS = 15000; // Maximum wait for the read-only server preparation request.
    var REFUND_COMMENT_MAX_LENGTH = 255; // Existing PaymentRefundForm reason limit.
    var REFUND_COMMENT_MIN_LENGTH = 3; // Existing PaymentRefundForm reason minimum.
    var timer;
    function notify(message) {
        if (IS_PREVIEW) {
            document.dispatchEvent(new CustomEvent('admin:previewnotice', { detail: { message: message } }));
            return;
        }
        var feedback = document.getElementById('orderViewFeedback');
        if (!feedback) {
            feedback = document.createElement('div');
            feedback.id = 'orderViewFeedback';
            feedback.className = 'order-view-feedback';
            feedback.setAttribute('role', 'status');
            feedback.setAttribute('aria-live', 'polite');
            document.body.appendChild(feedback);
        }
        feedback.textContent = message;
        feedback.hidden = false;
        clearTimeout(timer);
        timer = setTimeout(function () { feedback.hidden = true; }, FEEDBACK_MS);
    }
    document.addEventListener('click', function (event) {
        var button = event.target.closest('.js-order-copy');
        if (!button) return;
        var value = button.getAttribute('data-copy-value');
        if (!navigator.clipboard || !navigator.clipboard.writeText) {
            notify('Копирование недоступно. Выделите и скопируйте идентификатор вручную.');
            return;
        }
        navigator.clipboard.writeText(value).then(function () {
            notify('Идентификатор скопирован');
        }).catch(function () {
            notify('Браузер не разрешил копирование. Выделите идентификатор вручную.');
        });
    });
    function initOrderDates() {
        document.querySelectorAll('.js-order-date').forEach(function (node) {
            var original = node.getAttribute('title') || node.textContent;
            node.textContent = window.AdminTableDates.compactDate(original);
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initOrderDates);
    else initOrderDates();
    if (window.jQuery) window.jQuery(document).on('pjax:end.orderDetailDates', initOrderDates);
    function initRefundDraft() {
        var form = document.getElementById('orderRefundDraftForm');
        if (!form || form.dataset.refundBound) return;
        form.dataset.refundBound = 'true';
        var reason = document.getElementById('orderRefundReason');
        var comment = document.getElementById('orderRefundComment');
        var panel = document.getElementById('orderRefundCommentPanel');
        var prepareButton = document.getElementById('orderRefundPrepare');
        var endpoint = form.getAttribute('data-refund-prepare-url');
        var csrfToken = document.querySelector('meta[name="csrf-token"]');
        var csrfParam = document.querySelector('meta[name="csrf-param"]');
        var pending = false;
        function blockedMessage() {
            return form.getAttribute('data-refund-blocked-reason') ||
                (form.getAttribute('data-refund-eligibility') === 'insufficient_credits' ? 'Недостаточно кредитов для полного возврата' : '');
        }
        function syncPreparation() {
            prepareButton.disabled = pending || !!blockedMessage() || (!IS_PREVIEW && !(endpoint && csrfToken && csrfParam));
            prepareButton.title = blockedMessage();
        }
        syncPreparation();
        form.addEventListener('admin:refundstatechange', syncPreparation);
        // Native maxlength counts untrimmed UTF-16 units, unlike the server reason rule.
        comment.removeAttribute('maxlength');
        function syncReason() {
            var other = reason.value === 'other';
            panel.hidden = !other;
            comment.disabled = !other || pending;
            comment.required = other;
            comment.minLength = other ? REFUND_COMMENT_MIN_LENGTH : 0;
            comment.setCustomValidity('');
        }
        reason.addEventListener('change', syncReason);
        comment.addEventListener('input', function () { comment.setCustomValidity(''); });
        syncReason();
        form.addEventListener('submit', async function (event) {
            event.preventDefault();
            if (blockedMessage()) {
                notify(blockedMessage());
                return;
            }
            var reasonText = reason.value === 'other' ? comment.value.trim() : REFUND_REASON_LABELS[reason.value];
            var reasonLength = typeof reasonText === 'string' ? Array.from(reasonText).length : 0;
            comment.setCustomValidity(reason.value === 'other' && (reasonLength < REFUND_COMMENT_MIN_LENGTH || reasonLength > REFUND_COMMENT_MAX_LENGTH)
                ? 'Укажите пояснение от 3 до 255 символов' : '');
            if (pending || !form.reportValidity() || !REFUND_REASON_CODES.includes(reason.value) ||
                reasonLength < REFUND_COMMENT_MIN_LENGTH || reasonLength > REFUND_COMMENT_MAX_LENGTH) return;
            var payload = { order_id: form.getAttribute('data-order-id'), reason_code: reason.value,
                reason_text: reasonText, comment: reason.value === 'other' ? reasonText : '' };
            if (IS_PREVIEW) {
                // Static previews never invoke a configured financial backend.
                notify('Демо: причина заполнена. Для возврата нужна серверная проверка и подтверждение. Запрос не отправлен.');
                return;
            }
            if (!endpoint || !csrfToken || !csrfParam) {
                notify('Серверная подготовка возврата не подключена.');
                return;
            }
            var url;
            try {
                url = new URL(endpoint, location.href);
                if (url.origin !== location.origin) throw new Error('Unexpected origin');
            } catch (error) {
                notify('Некорректный адрес подготовки возврата.');
                return;
            }
            var body = new URLSearchParams(payload);
            body.set(csrfParam.content, csrfToken.content);
            var abort = new AbortController();
            var timeout = setTimeout(function () { abort.abort(); }, REFUND_REQUEST_TIMEOUT_MS);
            pending = true;
            prepareButton.disabled = true;
            form.setAttribute('aria-busy', 'true');
            reason.disabled = true;
            comment.disabled = true;
            notify('Проверяем возможность возврата…');
            try {
                var response = await fetch(url.href, { method: 'POST', credentials: 'same-origin',
                    headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
                    body: body, signal: abort.signal });
                var result = await response.json();
                if (!response.ok || result.ok !== true) {
                    var fields = result.error && result.error.fields;
                    var messages = fields && typeof fields === 'object' ? Object.values(fields).filter(function (message) { return typeof message === 'string'; }) : [];
                    notify(messages.length ? messages.join(' ') : result.error && result.error.message || 'Не удалось проверить возврат.');
                    return;
                }
                var data = result.data;
                if (!data || String(data.order_id) !== payload.order_id || typeof data.can_refund !== 'boolean') {
                    notify('Сервер вернул некорректный результат проверки.');
                    return;
                }
                // The host may show a confirmation UI; this event never initiates a refund itself.
                if (!form.isConnected) return;
                form.dispatchEvent(new CustomEvent('admin:refundprepared', { bubbles: true, detail: { request: payload, result: data } }));
                notify(data.can_refund ? 'Проверка пройдена. Для возврата требуется отдельное подтверждение.' :
                    (data.blockers && data.blockers[0] && data.blockers[0].message || 'Возврат сейчас недоступен.'));
            } catch (error) {
                notify(error.name === 'AbortError' ? 'Сервер не ответил вовремя. Повторите проверку.' : 'Не удалось связаться с сервером. Повторите проверку.');
            } finally {
                clearTimeout(timeout);
                pending = false;
                syncPreparation();
                form.removeAttribute('aria-busy');
                reason.disabled = false;
                syncReason();
            }
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initRefundDraft);
    else initRefundDraft();
    if (window.jQuery) window.jQuery(document).on('pjax:end.orderRefundDraft', initRefundDraft);
}());
